QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};
    QStringList out;
    const int weeks = minutes / (5 * 8 * 60);   // 2400
    const int days = (minutes % (5 * 8 * 60)) / (8 * 60);  // 480
    const int hours = (minutes % (8 * 60)) / 60;
    const int mins = minutes % 60;
    if (weeks) out << QString::number(weeks) + "w";
    if (days) out << QString::number(days) + "d";
    if (hours) out << QString::number(hours) + "h";
    if (mins) out << QString::number(mins) + "m";
    if (out.isEmpty()) out << "0m";
    return out.join(' ');
}
```

