{
    if (minutes < 0)
        return {};
    QStringList out;
    const int weeks = minutes / (5 * 8 * 60);
    const int days = (minutes % (5 * 8 * 60)) / (8 * 60);
    const int hours = (minutes % (8 * 60)) / 60;
    const int mins = minutes % 60;
