    CHECKEQ(formatEstimate(2880), QString("6d"), "2880");
    CHECKEQ(formatEstimate(5040), QString("2w 4h"), "5040");
}

void testModel()
{
    IssueModel model;
    // rowCount with a valid parent -> 0
    CHECKEQ(model.rowCount(QModelIndex()), 0, "valid parent rowCount");
    CHECKEQ(model.rowCount(), 2 ? 2 : 2, "invalid parent rowCount placeholder");

    // data: invalid index -> QVariant(); invalid role -> QVariant()
    QVariant badIdx = model.data(QModelIndex(), Qt::DisplayRole);
    CHECK(badIdx.isValid() == false, "data invalid index");
    model.addIssue({1, "a", 10, false});
    CHECK(model.data(QModelIndex(), Qt::DisplayRole).isValid() == false, "data invalid index after add");
    CHECK(model.data(model.index(0,0), 9999).isValid() == false, "data invalid role");
    CHECKEQ(model.data(model.index(0,0), Qt::DisplayRole).toString(), QString("a"), "display role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::IdRole).toInt(), 1, "id role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::EstimateRole).toInt(), 10, "estimate role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::ClosedRole).toBool(), false, "closed role");

    // setData: invalid index
    CHECK(model.setData(QModelIndex(), 5, IssueModel::EstimateRole) == false, "setData invalid index");
    // setData: other role
    CHECK(model.setData(model.index(0,0), "x", Qt::DisplayRole) == false, "setData other role");
    // setData: negative estimate
    QSignalSpy spy(&model, &QAbstractItemModel::dataChanged);
    CHECK(model.setData(model.index(0,0), -1, IssueModel::EstimateRole) == false, "setData negative");
    CHECK(spy.count() == 0, "setData negative emits nothing");
    CHECKEQ(model.data(model.index(0,0), IssueModel::EstimateRole).toInt(), 10, "estimate unchanged after negative");
    // setData: unchanged value
    CHECK(model.setData(model.index(0,0), 10, IssueModel::EstimateRole) == false, "setData unchanged");
    CHECK(spy.count() == 0, "setData unchanged emits nothing");
    // setData: valid change names exactly the role
    CHECK(model.setData(model.index(0,0), 25, IssueModel::EstimateRole) == true, "setData valid");
    CHECK(spy.count() == 1, "setData valid emits once");
    CHECK(spy.at(0).at(2).toList().at(0).toInt() == IssueModel::EstimateRole, "dataChanged names changed role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::EstimateRole).toInt(), 25, "estimate updated");
    // ClosedRole change
    CHECK(model.setData(model.index(0,0), true, IssueModel::ClosedRole) == true, "setData closed");
    CHECK(spy.count() == 2, "setData closed emits once");
    CHECK(spy.at(1).at(2).toList().at(0).toInt() == IssueModel::ClosedRole, "dataChanged names closed role");

    // addIssue: duplicate id -> false, no change
    const int before = model.rowCount();
    QSignalSpy ins(&model, &QAbstractItemModel::rowsInserted);
    CHECK(model.addIssue({1, "dup", 99, false}) == false, "addIssue duplicate id");
    CHECK(model.rowCount() == before, "addIssue duplicate changes nothing");
    CHECK(ins.count() == 0, "addIssue duplicate emits no insert");
    // addIssue: new id
    CHECK(model.addIssue({2, "b", 20, false}) == true, "addIssue new");
    CHECK(ins.count() == 1, "addIssue new emits insert");

    // removeIssue: nonexistent -> false
    QSignalSpy rem(&model, &QAbstractItemModel::rowsRemoved);
    CHECK(model.removeIssue(999) == false, "removeIssue nonexistent");
    CHECK(rem.count() == 0, "removeIssue nonexistent emits nothing");
    // removeIssue: existing
    CHECK(model.removeIssue(2) == true, "removeIssue existing");
    CHECK(rem.count() == 1, "removeIssue existing emits once");
    CHECKEQ(rem.at(0).at(2).toInt(), 0, "removeIssue last row index");
}

void testSummary()
{
    IssueModel model;
    model.addIssue({1, "a", 10, false});
    model.addIssue({2, "b", 20, true});
    QSignalSpy changed(& /*summary*/ 0 ? nullptr : /*placeholder*/ nullptr); (void)changed;

    BacklogSummary summary(&model);
    CHECKEQ(summary.openMinutes(), 10, "open sum");

    // connect after construction; verify emit-on-change and no-emit-when-unchanged
    QSignalSpy spy(&summary, &BacklogSummary::totalChanged);
    // change an open issue's estimate -> total changes
    model.setData(model.index(0,0), 40, IssueModel::EstimateRole);
    CHECK(spy.count() == 1, "summary emits on value change");
    CHECKEQ(summary.openMinutes(), 40, "summary updated");
    // change a closed issue's estimate -> total unchanged -> no emit
    model.setData(model.index(1,0), 99, IssueModel::EstimateRole);
    CHECK(spy.count() == 1, "summary no emit when total unchanged");
    CHECKEQ(summary.openMinutes(), 40, "summary unchanged value");
    // add open issue -> emit
    model.addIssue({3, "c", 5, false});
    CHECK(spy.count() == 2, "summary emits on insert");
    CHECKEQ(summary.openMinutes(), 45, "summary after insert");
    // remove open issue -> emit
    model.removeIssue(3);
    CHECK(spy.count() == 3, "summary emits on remove");
    CHECKEQ(summary.openMinutes(), 40, "summary after remove");

    // after model destroyed, openMinutes() == 0
    delete &model;
    CHECKEQ(summary.openMinutes(), 0, "openMinutes after model destroyed");
}

int main()
{
    testParse();
    testFormat();
    testModel();
    testSummary();
    if (failures == 0)
        qInfo() << "ALL SPEC CHECKS PASSED";
    else
        qInfo() << "SPEC CHECKS FAILED:" << failures;
    return failures ? 1 : 0;
}

