#include <QSignalSpy>
#include <QString>
#include <QDebug>
#include "estimate.h"
#include "issuemodel.h"
#include "backlogsummary.h"

static int failures = 0;
#define CHECK(cond, msg) do { if (!(cond)) { qCritical() << "FAIL:" << msg; ++failures; } } while (0)
#define CHECKEQ(a, b, msg) do { if ((a) != (b)) { qCritical() << "FAIL:" << msg << "got" << (a) << "want" << (b); ++failures; } } while (0)

void testParse()
{
    CHECKEQ(parseEstimate("1d"), 480, "1d");
    CHECKEQ(parseEstimate("1w"), 2400, "1w");
    CHECKEQ(parseEstimate("30m 1h"), 90, "any order");
    CHECKEQ(parseEstimate(" 1h "), 60, "surrounding spaces");
    CHECKEQ(parseEstimate("1d 2h 30m"), 630, "combined");
    CHECKEQ(parseEstimate(""), -1, "empty");
    CHECKEQ(parseEstimate("  "), -1, "only spaces");
    CHECKEQ(parseEstimate("1x"), -1, "unknown unit");
    CHECKEQ(parseEstimate("d"), -1, "missing number");
    CHECKEQ(parseEstimate("-5h"), -1, "negative");
    CHECKEQ(parseEstimate("1d 2x"), -1, "unknown unit mid-string");
    CHECKEQ(parseEstimate("0h"), 0, "zero");
}

void testFormat()
{
    CHECKEQ(formatEstimate(630), QString("1d 2h 30m"), "630");
    CHECKEQ(formatEstimate(2400), QString("1w"), "2400");
    CHECKEQ(formatEstimate(0), QString("0m"), "0");
    CHECKEQ(formatEstimate(-10), QString(""), "negative");
    CHECKEQ(formatEstimate(90), QString("1h 30m"), "90");
    CHECKEQ(formatEstimate(480), QString("1d"), "480");
    CHECKEQ(formatEstimate(120), QString("2h"), "120");
    CHECKEQ(formatEstimate(2880), QString("6d"), "2880");
    CHECKEQ(formatEstimate(5040), QString("2w 4h"), "5040");
}

void testModel()
{
    IssueModel model;
    // rowCount with a valid parent -> 0
    CHECKEQ(model.rowCount(QModelIndex()), 0, "valid parent rowCount");
    CHECKEQ(model.rowCount(), 0, "invalid parent rowCount before add");

    // data: invalid index -> QVariant(); invalid role -> QVariant()
    QVariant badIdx = model.data(QModelIndex(), Qt::DisplayRole);
    CHECK(badIdx.isValid() == false, "data invalid index");
    model.addIssue({1, "a", 10, false});
    CHECK(model.data(QModelIndex(), Qt::DisplayRole).isValid() == false, "data invalid index after add");
    CHECK(model.data(model.index(0,0), 9999).isValid() == false, "data invalid role");
    CHECKEQ(model.data(model.index(0,0), Qt::DisplayRole).toString(), QString("a"), "display role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::IdRole).toInt(), 1, "id role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::EstimateRole).toInt(), 10, "estimate role");
    CHECKEQ(model.data(model.index(0,0), IssueModel::ClosedRole).toBool(), false, "closed role");

    // setData: invalid index
    CHECK(model.setData(QModelIndex(), 5, IssueModel::EstimateRole) == false, "setData invalid index");
    // setData: other role
